include!("/workspace/challenge/src/lib.rs");

fn exact_debit(amount: u64, fee: u64) -> u128 {
    let numerator = (amount as u128) + ((fee as u128) << 64);
    let gross_fee = numerator / 1_000_000 + if numerator % 1_000_000 != 0 { 1 } else { 0 };
    (amount / 2) as u128 + gross_fee
}

fn check(balance: u64, amount: u64, fee: u64) {
    let debit = exact_debit(amount, fee);
    let expected = if debit <= balance as u128 {
        Some(Authorization { total_debit: debit as u64 })
    } else {
        None
    };
    assert_eq!(authorize(balance, amount, fee), expected,
        "balance={balance}, amount={amount}, fee={fee}, exact={debit}");
    let gross = debit - (amount / 2) as u128;
    let expected_fee = if gross <= u64::MAX as u128 { Some(gross as u64) } else { None };
    assert_eq!(u128_math::div_round_up_fee(amount, fee), expected_fee);
}

fn random(state: &mut u64) -> u64 {
    *state ^= *state << 13;
    *state ^= *state >> 7;
    *state ^= *state << 17;
    *state
}

fn main() {
    let values = [0, 1, 2, 3, 999_999, 1_000_000, 1_000_001,
        (1u64 << 32) - 1, 1u64 << 32, (1u64 << 32) + 1,
        4_294_967_295_000_000, 4_294_967_295_000_001,
        u64::MAX / 2, u64::MAX - 1, u64::MAX];
    let mut checks = 0;
    for amount in values {
        for fee in values {
            for balance in values {
                check(balance, amount, fee);
                checks += 1;
            }
            let debit = exact_debit(amount, fee);
            if debit <= u64::MAX as u128 {
                let debit = debit as u64;
                check(debit, amount, fee);
                if debit > 0 { check(debit - 1, amount, fee); }
                if debit < u64::MAX { check(debit + 1, amount, fee); }
            }
        }
    }
    let mut state = 0x7dca_519b_efa3_6021;
    for i in 0..1_000_000 {
        let amount = random(&mut state);
        let fee_sample = random(&mut state);
        let fee = if i % 2 == 0 { fee_sample % 1_000_001 } else { fee_sample };
        let balance = random(&mut state);
        check(balance, amount, fee);
        let debit = exact_debit(amount, fee);
        if debit <= u64::MAX as u128 {
            let debit = debit as u64;
            check(debit, amount, fee);
            if debit > 0 { check(debit - 1, amount, fee); }
        }
        checks += 1;
    }
    println!("Passed {checks} boundary/random cases plus exact-affordability boundary checks.");
}
